struct Shelf<Item> {
    private var items: [Item] = []
    mutating func add(_ item: Item) { items.append(item) }
    func first() -> Item? { items.first }
    var count: Int { items.count }
}
extension Shelf where Item: Equatable {
    func contains(_ item: Item) -> Bool { items.contains(item) }
}
struct Preview { let id: Int }
var previews = Shelf<Preview>()
previews.add(Preview(id: 71))
print(previews.first()?.id ?? 0)
var ids = Shelf<Int>()
ids.add(71)
print(ids.contains(71))

Вывод 71, true; Preview не обязан быть Equatable для хранения.

func replacing<T: Equatable>(
    _ values: [T], old: T, new: T
) -> [T] {
    var result: [T] = []
    for value in values { result.append(value == old ? new : value) }
    return result
}
print(replacing([71, 72, 71], old: 71, new: 99))

Та же generic-связь сохранена в аргументах и результате; Equatable нужен только для сравнения.
